import type {ConversationLevelVariant} from "../conversation-families/types";
import {dossiers as originalDossiers, stages, interviewQuestions as originalInterviews, values as originalValues, finalQuestions as originalFinals, languageSupport as originalSupport, type Dossier} from "./data";

export type AgencyLevel="A1"|"A2"|"B1"|"B2"|"C1"|"C2";
export type FinalQuestion={q:string;f:string;c:string};
export type AgencyCopy={
  kicker:string;opening:string;warmup:string;sealedTitle:string;sealedTask:string;
  fileTeacher:string;verdict:string;interviewTitle:string;interviewTask:string;
  balanceTitle:string;balanceTask:string;balanceSentence:(selected:string[])=>string;balanceFollowup:string;
  rewriteTitle:string;rewriteTask:string;rewriteQuestions:string;rippleTask:string;
  finalTitle:string;finalTask:string;finalReveal:string;finalChallengeLabel:string;closingTitle:string;closingTask:string;
  paceShort:string;paceLong:string;
};
export type AgencyActivities={
  dossiers:Dossier[];
  stages:readonly (readonly [string,string])[];
  interviewQuestions:readonly string[];
  values:readonly string[];
  finalQuestions:readonly FinalQuestion[];
  languageSupport:Record<string,readonly string[]>;
  copy:AgencyCopy;
  hook:string;cover:string;alt:string;
};

type CaseRow=readonly [
  id:string,door:string,signal:string,decision:string,probe:string,
  consequence:string,consequencePrompt:string,cost:string,reconsider:string,
  person:string,role:string,line:string,teacher:string,
  rewrite:string,rippleOne:string,rippleTwo:string,finalPrompt:string,
];
function files(level:Exclude<AgencyLevel,"C1">,rows:readonly CaseRow[]):Dossier[]{
  if(rows.length!==6)throw new Error(`${level}: six doors need complete stories`);
  return rows.map(([id,door,signal,decision,probe,consequence,consequencePrompt,cost,reconsider,name,role,line,teacher,rewrite,rippleOne,rippleTwo,finalPrompt],index)=>({
    id,code:`VP-${level}-${String(index+1).padStart(2,"0")}`,door,signal,decision,probe,
    consequence,consequencePrompt,cost,reconsider,
    person:{name,role,line,teacher},rewrite,ripples:[rippleOne,rippleTwo],finalPrompt,
  }));
}
function finals(rows:readonly (readonly [string,string,string])[]):FinalQuestion[]{
  if(rows.length<6)throw new Error("At least six final conversation paths are required");
  return rows.map(([q,f,c])=>({q,f,c}));
}
function activities(level:Exclude<AgencyLevel,"C1">,data:Omit<AgencyActivities,"stages"|"cover">):AgencyActivities{
  return {...data,stages,cover:`/conversation-variants/agencia-vidas-paralelas-${level.toLowerCase()}.webp`};
}

